const items = $input.all();

return items.map(item => {
  let aiMessage = '';

  // Extract message from different AI providers
  if (item.json.choices) {
    // OpenAI response format
    aiMessage = item.json.choices[0]?.message?.content || '';
  } else if (item.json.content) {
    // Claude response format
    aiMessage = item.json.content[0]?.text || '';
  } else if (item.json.output) {
    // n8n AI Agent response format
    aiMessage = item.json.output || '';
  }

  // Clean up the message
  aiMessage = aiMessage.trim().replace(/^["']|["']$/g, '');

  // Fallback if AI fails
  if (!aiMessage || aiMessage.length < 10) {
    const firstName = item.json.first_name || 'there';
    const company = item.json.Company || 'your company';
    aiMessage = `Hi ${firstName}, I'd love to connect and learn more about your work at ${company}!`;
  }

  return {
    json: {
      ...item.json,
      final_message: aiMessage,
      ai_generated: true,
      target_name: `${item.json.first_name || ''} ${item.json.last_name || ''}`.trim()
    }
  };
});

const items = $input.all();

return items.map(item => {
  const success = item.json.object === 'UserInvitationSent' && item.json.invitation_id;
  const currentDate = new Date().toISOString().split('T')[0];

  return {
    json: {
      ...item.json,
      invitation_success: success,
      new_status: success ? 'sent' : 'error',
      sent_date: success ? currentDate : '',
      error_message: item.json.error || (success ? `Invitation sent (ID: ${item.json.invitation_id})` : 'Failed to send'),
      invitation_id: item.json.invitation_id || '',
      update_timestamp: new Date().toISOString()
    }
  };
});

